import{_ as t,o as e,c as o,a2 as l}from"./chunks/framework.DaAAbehN.js";const c=JSON.parse('{"title":"第 11 课：自动化任务 —— 让 Codex 帮你\\"跑腿\\"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/modules/module-3/lesson-11.md","filePath":"zh/modules/module-3/lesson-11.md"}'),i={name:"zh/modules/module-3/lesson-11.md"};function s(d,a,r,n,h,u){return e(),o("div",null,[...a[0]||(a[0]=[l(`<h1 id="第-11-课-自动化任务-——-让-codex-帮你-跑腿" tabindex="-1">第 11 课：自动化任务 —— 让 Codex 帮你&quot;跑腿&quot; <a class="header-anchor" href="#第-11-课-自动化任务-——-让-codex-帮你-跑腿" aria-label="Permalink to &quot;第 11 课：自动化任务 —— 让 Codex 帮你&quot;跑腿&quot;&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：学会用 Codex 执行重复性任务，理解&quot;一次性任务&quot;与&quot;可复用流程&quot;的区别<br> ⏱️ <strong>预计时长</strong>：25 分钟<br> 🎯 <strong>本节节奏</strong>：先演示 → 后讲解 → 再实操</p></blockquote><hr><h2 id="一、什么是-自动化任务" tabindex="-1">一、什么是&quot;自动化任务&quot;？ <a class="header-anchor" href="#一、什么是-自动化任务" aria-label="Permalink to &quot;一、什么是&quot;自动化任务&quot;？&quot;">​</a></h2><p>自动化任务就是：<strong>你告诉 Codex 要做什么，它自己一步步完成整个过程，不需要你反复操作。</strong></p><h3 id="生活中的类比" tabindex="-1">生活中的类比 <a class="header-anchor" href="#生活中的类比" aria-label="Permalink to &quot;生活中的类比&quot;">​</a></h3><p>假设你要搬家：</p><ul><li><strong>手动方式</strong>：你自己打包每一样东西，贴标签，搬上车</li><li><strong>自动化方式</strong>：你告诉一个助手&quot;我要搬家，把这些东西搬到新家&quot;，助手自己去打包、贴标签、搬运</li></ul><p>Codex 就是那个&quot;助手&quot;。</p><hr><h2 id="二、实操一-批量重命名一批文件" tabindex="-1">二、实操一：批量重命名一批文件 <a class="header-anchor" href="#二、实操一-批量重命名一批文件" aria-label="Permalink to &quot;二、实操一：批量重命名一批文件&quot;">​</a></h2><h3 id="场景" tabindex="-1">场景 <a class="header-anchor" href="#场景" aria-label="Permalink to &quot;场景&quot;">​</a></h3><p>你下载了 50 张图片，文件名都是 <code>download_001.jpg</code>, <code>download_002.jpg</code>... 你想改成更有意义的名字。</p><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>打开图片文件夹作为工作区</li><li>输入指令：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我把这些图片按日期重命名，格式为&quot;拍摄日期_序号.jpg&quot;</span></span>
<span class="line"><span>例如：2026-07-20_001.jpg</span></span></code></pre></div></li><li>Codex 会读取每张图片的 EXIF 信息（如果有的话），然后批量重命名</li></ol><h3 id="更多批量操作示例" tabindex="-1">更多批量操作示例 <a class="header-anchor" href="#更多批量操作示例" aria-label="Permalink to &quot;更多批量操作示例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你的需求</th><th>指令示例</th></tr></thead><tbody><tr><td>统一扩展名大小写</td><td>&quot;把所有 .JPG 改成 .jpg&quot;</td></tr><tr><td>添加前缀/后缀</td><td>&quot;在所有文件名前面加上&#39;项目A-&#39;&quot;</td></tr><tr><td>删除特定字符</td><td>&quot;去掉所有文件名中的空格和下划线&quot;</td></tr><tr><td>按规则重命名</td><td>&quot;把&#39;IMG_<em>.jpg&#39;改成&#39;旅行_</em>.jpg&#39;&quot;</td></tr></tbody></table><hr><h2 id="三、实操二-自动下载并整理资料" tabindex="-1">三、实操二：自动下载并整理资料 <a class="header-anchor" href="#三、实操二-自动下载并整理资料" aria-label="Permalink to &quot;三、实操二：自动下载并整理资料&quot;">​</a></h2><h3 id="场景-1" tabindex="-1">场景 <a class="header-anchor" href="#场景-1" aria-label="Permalink to &quot;场景&quot;">​</a></h3><p>你需要收集某个主题的网上资料，但不想一个个点开链接复制粘贴。</p><h3 id="操作步骤-1" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤-1" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li><p>在 Codex 中输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我搜索&quot;远程办公最佳实践&quot;的最新文章，找出排名前 5 的结果，把每个结果的标题、摘要和链接整理成一个文档</span></span></code></pre></div></li><li><p>Codex 会：</p><ul><li>联网搜索相关信息</li><li>提取前 5 条结果</li><li>创建一个 Markdown 文件保存整理后的内容</li></ul></li><li><p>你可以进一步要求：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个文档翻译成中文</span></span></code></pre></div><p>或</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据这些资料，写一篇关于远程办公的推荐清单</span></span></code></pre></div></li></ol><hr><h2 id="四、理解-一次性任务-vs-可重复使用的自动化流程" tabindex="-1">四、理解&quot;一次性任务&quot;vs&quot;可重复使用的自动化流程&quot; <a class="header-anchor" href="#四、理解-一次性任务-vs-可重复使用的自动化流程" aria-label="Permalink to &quot;四、理解&quot;一次性任务&quot;vs&quot;可重复使用的自动化流程&quot;&quot;">​</a></h2><h3 id="一次性任务" tabindex="-1">一次性任务 <a class="header-anchor" href="#一次性任务" aria-label="Permalink to &quot;一次性任务&quot;">​</a></h3><p>比如：&quot;帮我把这个文件夹里的 PDF 文件合并成一个&quot;</p><ul><li>做一次就完了</li><li>下次再做同样的事，需要重新告诉 Codex</li></ul><h3 id="可重复使用的流程" tabindex="-1">可重复使用的流程 <a class="header-anchor" href="#可重复使用的流程" aria-label="Permalink to &quot;可重复使用的流程&quot;">​</a></h3><p>比如：&quot;每次有新邮件时，自动提取附件中的表格数据并保存到 Excel&quot;</p><ul><li>可以设置成定期执行</li><li>或者做成脚本/模板，随时调用</li></ul><blockquote><p>💡 <strong>提示</strong>：Codex 不仅能做一次性任务，还能帮你编写可复用的脚本。当你发现某个任务经常要做时，可以让 Codex 把它变成一个自动化脚本。</p></blockquote><hr><h2 id="五、实操三-创建你的第一个自动化脚本" tabindex="-1">五、实操三：创建你的第一个自动化脚本 <a class="header-anchor" href="#五、实操三-创建你的第一个自动化脚本" aria-label="Permalink to &quot;五、实操三：创建你的第一个自动化脚本&quot;">​</a></h2><h3 id="任务" tabindex="-1">任务 <a class="header-anchor" href="#任务" aria-label="Permalink to &quot;任务&quot;">​</a></h3><p>让 Codex 帮你写一个&quot;每日工作日报&quot;的自动生成脚本。</p><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>准备一个包含每日工作记录的文件夹</li><li>输入指令：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一个 Python 脚本，读取这个文件夹里所有的日志文件，</span></span>
<span class="line"><span>统计每天的工作条目数，生成一个汇总报告</span></span></code></pre></div></li><li>Codex 会生成一个可复用的脚本</li><li>以后每天早上运行一次这个脚本，就能自动得到昨天的工作汇总</li></ol><hr><h2 id="六、本节实操任务清单" tabindex="-1">六、本节实操任务清单 <a class="header-anchor" href="#六、本节实操任务清单" aria-label="Permalink to &quot;六、本节实操任务清单&quot;">​</a></h2><p>请按顺序完成以下任务：</p><ul><li>[ ] 让 Codex 批量重命名一批文件</li><li>[ ] 让 Codex 联网搜索资料并整理成文档</li><li>[ ] 尝试让 Codex 写一个简单的自动化脚本</li><li>[ ] 思考：你工作中有哪些重复性任务可以交给 Codex 自动化？</li></ul><hr><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>自动化任务</td><td>让 Codex 代替你完成重复性工作</td></tr><tr><td>批量操作</td><td>重命名、移动、分类、格式化等</td></tr><tr><td>联网检索</td><td>搜索 + 整理 + 总结</td></tr><tr><td>一次性 vs 可复用</td><td>简单任务直接说，复杂任务写脚本</td></tr></tbody></table><hr><h2 id="八、下一步" tabindex="-1">八、下一步 <a class="header-anchor" href="#八、下一步" aria-label="Permalink to &quot;八、下一步&quot;">​</a></h2><p><a href="./../module-4/lesson-12.html">→ 进入模块四：实用技巧</a></p>`,48)])])}const q=t(i,[["render",s]]);export{c as __pageData,q as default};
